-- MemeReach off-chain schema. Monetary fields use integer cents; Solana amounts use bigint base units.
create table if not exists organizations (id uuid primary key, name text not null, kind text not null check (kind in ('advertiser','publisher','platform')), created_at timestamptz not null default now());
create table if not exists users (id uuid primary key, email text unique not null, display_name text not null, created_at timestamptz not null default now());
create table if not exists organization_members (organization_id uuid references organizations(id) on delete restrict, user_id uuid references users(id) on delete restrict, role text not null, created_at timestamptz not null default now(), primary key (organization_id, user_id));
create table if not exists advertiser_profiles (organization_id uuid primary key references organizations(id) on delete restrict, website text, disclosure_text text, created_at timestamptz not null default now());
create table if not exists publisher_profiles (organization_id uuid primary key references organizations(id) on delete restrict, payout_status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists publisher_domains (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, domain text unique not null, verification_status text not null default 'pending', verified_at timestamptz, created_at timestamptz not null default now());
create table if not exists publisher_domain_verifications (id uuid primary key, domain_id uuid references publisher_domains(id) on delete restrict, method text not null, token_hash text not null, status text not null, created_at timestamptz not null default now());
create table if not exists ad_placements (id uuid primary key, domain_id uuid references publisher_domains(id) on delete restrict, name text not null, format text not null, width integer, height integer, category text not null, floor_cents integer not null default 0, status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists campaigns (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, name text not null, objective text not null, status text not null, budget_cents bigint not null check (budget_cents > 0), bid_cents bigint not null check (bid_cents > 0), pricing_model text not null, start_at timestamptz, end_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists campaign_tokens (campaign_id uuid primary key references campaigns(id) on delete restrict, mint text not null, cluster text not null, token_program text, token_name text, token_symbol text, supply_base_units numeric, decimals integer, created_at timestamptz not null default now());
create table if not exists creatives (id uuid primary key, campaign_id uuid references campaigns(id) on delete restrict, format text not null, headline text not null, description text not null, destination_url text not null, asset_key text, disclosure_required boolean not null default true, created_at timestamptz not null default now());
create table if not exists audience_rules (id uuid primary key, campaign_id uuid references campaigns(id) on delete restrict, rule_type text not null, value_json jsonb not null, created_at timestamptz not null default now());
create table if not exists campaign_placements (campaign_id uuid references campaigns(id) on delete restrict, placement_id uuid references ad_placements(id) on delete restrict, primary key (campaign_id, placement_id));
create table if not exists campaign_schedules (campaign_id uuid primary key references campaigns(id) on delete restrict, start_at timestamptz not null, end_at timestamptz, pacing text not null default 'even');
create table if not exists campaign_budget_reservations (id uuid primary key, campaign_id uuid references campaigns(id) on delete restrict, amount_cents bigint not null check (amount_cents > 0), status text not null, idempotency_key text unique not null, created_at timestamptz not null default now());
create table if not exists funding_requests (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, amount_cents bigint not null check (amount_cents > 0), currency text not null, payment_reference text not null, evidence_key text, status text not null default 'pending', idempotency_key text unique not null, created_at timestamptz not null default now());
create table if not exists ledger_accounts (id uuid primary key, organization_id uuid unique references organizations(id) on delete restrict, currency text not null, created_at timestamptz not null default now());
create table if not exists ledger_entries (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, amount_cents bigint not null, currency text not null, entry_type text not null, status text not null, reference text not null, idempotency_key text unique, audit_metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table if not exists publisher_earnings (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, amount_cents bigint not null, status text not null, source_event_id uuid, created_at timestamptz not null default now());
create table if not exists payout_requests (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, amount_cents bigint not null check (amount_cents > 0), status text not null default 'pending', idempotency_key text unique not null, created_at timestamptz not null default now());
create table if not exists ad_requests (id uuid primary key, placement_id uuid references ad_placements(id) on delete restrict, request_id text unique not null, sandbox boolean not null default false, created_at timestamptz not null default now());
create table if not exists impression_events (id uuid primary key, event_id text unique not null, request_id text not null, campaign_id uuid references campaigns(id) on delete restrict, placement_id uuid references ad_placements(id) on delete restrict, billable boolean not null default false, created_at timestamptz not null default now());
create table if not exists click_events (id uuid primary key, event_id text unique not null, request_id text not null, campaign_id uuid references campaigns(id) on delete restrict, placement_id uuid references ad_placements(id) on delete restrict, valid boolean not null default false, created_at timestamptz not null default now());
create table if not exists conversion_events (id uuid primary key, event_id text unique not null, request_id text not null, campaign_id uuid references campaigns(id) on delete restrict, placement_id uuid references ad_placements(id) on delete restrict, created_at timestamptz not null default now());
create table if not exists fraud_signals (id uuid primary key, event_id text, signal_type text not null, evidence jsonb not null, created_at timestamptz not null default now());
create table if not exists token_screenings (id uuid primary key, mint text not null, cluster text not null, status text not null, risk_score integer, data_completeness integer not null, confidence text not null, screening_version text not null, source_observed_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), unique (mint, cluster, screening_version));
create table if not exists token_screening_signals (id uuid primary key, screening_id uuid references token_screenings(id) on delete restrict, source text not null, signal text not null, value text, status text not null, explanation text not null, observed_at timestamptz not null);
create table if not exists moderation_cases (id uuid primary key, campaign_id uuid references campaigns(id) on delete restrict, status text not null, created_at timestamptz not null default now());
create table if not exists moderation_decisions (id uuid primary key, case_id uuid references moderation_cases(id) on delete restrict, reviewer_id uuid references users(id) on delete restrict, decision text not null, reason text not null, created_at timestamptz not null default now());
create table if not exists appeals (id uuid primary key, case_id uuid references moderation_cases(id) on delete restrict, status text not null, body text not null, created_at timestamptz not null default now());
create table if not exists notifications (id uuid primary key, user_id uuid references users(id) on delete restrict, kind text not null, payload jsonb not null, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key, organization_id uuid references organizations(id) on delete restrict, actor_id uuid references users(id) on delete restrict, action text not null, entity_type text not null, entity_id text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());

create index if not exists idx_campaigns_org_status on campaigns(organization_id, status);
create index if not exists idx_screenings_mint_expiry on token_screenings(mint, expires_at);
create index if not exists idx_events_request on impression_events(request_id);
create index if not exists idx_audit_org_time on audit_logs(organization_id, created_at desc);

-- Historical ledger entries are append-only. Corrections are compensating entries with their own reference.
create or replace function prevent_ledger_mutation() returns trigger language plpgsql as $$ begin raise exception 'ledger entries are immutable; create a compensating entry'; end; $$;
create trigger ledger_entries_immutable before update or delete on ledger_entries for each row execute function prevent_ledger_mutation();
